"use strict";(globalThis.webpackChunklearngenomics_dev||=[]).push([[5435],{3370(e,t,n){n.r(t),n.d(t,{assets:()=>m,contentTitle:()=>d,default:()=>g,frontMatter:()=>h,metadata:()=>i,toc:()=>u});var a=n.cw((e,t)=>{const a=n.p+"assets/images/2.8-trunk-and-branches-dark-2a15ee84c0177bb72147e56d00ad263f.svg";n.d(t,["A",0,a])}),s=n.cw((e,t)=>{const a=n.p+"assets/images/2.9-treatment-selects-dark-50ac2d18cf82934b3c86f00653272342.svg";n.d(t,["A",0,a])}),o=n.cw((e,t)=>{const a=n.p+"assets/images/2.8-trunk-and-branches-06d4708c1e647af66e477847fdb4c6d1.svg";n.d(t,["A",0,a])}),r=n.cw((e,t)=>{const a=n.p+"assets/images/2.9-treatment-selects-48300916a6b8d9398e71382eb110c09f.svg";n.d(t,["A",0,a])});const i=JSON.parse('{"id":"cancer-biology/how-tumors-evolve","title":"How Tumors Evolve","description":"What Is Cancer? described how a tumor grows","source":"@site/docs/02-cancer-biology/05-how-tumors-evolve.md","sourceDirName":"02-cancer-biology","slug":"/cancer-biology/how-tumors-evolve","permalink":"/docs/cancer-biology/how-tumors-evolve","draft":false,"unlisted":false,"editUrl":"https://github.com/stjude/learngenomics.dev/tree/main/docs/02-cancer-biology/05-how-tumors-evolve.md","tags":[],"version":"current","sidebarPosition":5,"frontMatter":{"title":"How Tumors Evolve"},"sidebar":"tutorialSidebar","previous":{"title":"Signaling Pathways","permalink":"/docs/cancer-biology/signaling-pathways"},"next":{"title":"Inherited Risk","permalink":"/docs/cancer-biology/inherited-risk"}}');var l=n(4848),c=n(8453);const h={title:"How Tumors Evolve"},d=void 0,m={},u=[{value:"Evolution Starts Before Cancer",id:"evolution-starts-before-cancer",level:2},{value:"Trunk and Branches",id:"trunk-and-branches",level:2},{value:"Reading Clones in the Data",id:"reading-clones-in-the-data",level:2},{value:"Faster Change",id:"faster-change",level:2},{value:"Spreading",id:"spreading",level:2},{value:"Surviving Treatment",id:"surviving-treatment",level:2},{value:"Up Next",id:"up-next",level:2}];function f(e){const t={a:"a",em:"em",figcaption:"figcaption",figure:"figure",h2:"h2",img:"img",li:"li",p:"p",span:"span",strong:"strong",ul:"ul",...(0,c.R)(),...e.components};return(0,l.jsxs)(l.Fragment,{children:[(0,l.jsxs)(t.p,{children:[(0,l.jsx)(t.a,{href:"/docs/cancer-biology/what-is-cancer#how-cancer-starts",children:"What Is Cancer?"})," described how a tumor grows\nfrom a single cell, with each new driver mutation setting off another wave of growth.\nThat process is evolution by natural selection. The cells in a tumor differ from one\nanother, some of them survive and divide better than the rest, and their descendants\ntake over. This page follows that population of cells as it branches, spreads and\nsurvives treatment, and shows how its history can be read from sequencing data."]}),"\n",(0,l.jsx)(t.h2,{id:"evolution-starts-before-cancer",children:"Evolution Starts Before Cancer"}),"\n",(0,l.jsxs)(t.p,{children:["A ",(0,l.jsx)(t.strong,{children:"clone"})," is a group of cells that all descend from one cell, so they share the\nmutations that cell carried. Clones carrying mutations in cancer genes are common in\nhealthy tissue. In 234 small pieces of normal, sun-exposed skin from the eyelids of four\npeople, several cancer genes were under strong selection, and 18 to 32% of the skin\ncells carried a selected mutation. The skin was a patchwork of thousands of competing\nclones, yet it still did its job (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1126/science.aaa6806",children:"Martincorena et al.,\n2015"}),"). In the lining of the esophagus in\nmiddle-aged and older people, clones with ",(0,l.jsx)(t.em,{children:"NOTCH1"})," mutations covered 12 to 80% of the\ncells. ",(0,l.jsx)(t.em,{children:"NOTCH1"})," mutations were several times more common in the normal esophagus than in\nesophageal cancers, so a mutation in a cancer gene doesn't by itself make a cell\ncancerous (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1126/science.aau3879",children:"Martincorena et al., 2018"}),")."]}),"\n",(0,l.jsxs)(t.p,{children:["Blood shows the same thing. In blood DNA from more than 12,000 people, clones of blood\ncells carrying new mutations, most often in genes linked to blood cancers, were found in\n10% of those older than 65 but in only 1% of those younger than 50. Over the next few\nyears, people with one of these clones developed blood cancers at about 13 times the\nrate of those without (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1056/NEJMoa1409405",children:"Genovese et al., 2014"}),")."]}),"\n",(0,l.jsxs)(t.p,{children:["Tumors carry a record of this early history. Using whole genomes from 2,658 tumors of 38\nkinds of cancer, researchers worked out the likely order in which many of each tumor's\nmutations arose. Driver mutations often appeared many years, and sometimes decades,\nbefore the cancer was diagnosed (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1038/s41586-019-1907-7",children:"Gerstung et al.,\n2020"}),")."]}),"\n",(0,l.jsx)(t.h2,{id:"trunk-and-branches",children:"Trunk and Branches"}),"\n",(0,l.jsxs)(t.p,{children:["The cancer cells in a tumor descend from a common ancestor, so they all carry its\nmutations. These shared mutations are ",(0,l.jsx)(t.strong,{children:"clonal"}),". A mutation that arises later is passed\non only to the descendants of the cell where it happened, a ",(0,l.jsx)(t.strong,{children:"subclone"}),", and it is\n",(0,l.jsx)(t.strong,{children:"subclonal"}),". If a subclone later takes over the whole tumor, its mutations become\nclonal too. Drawn as a family tree, the clonal mutations form the trunk and the\nsubclones form the branches (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1101/cshperspect.a026625",children:"Dentro et al.,\n2017"}),")."]}),"\n",(0,l.jsxs)(t.p,{children:["The branches can grow in different parts of a tumor. When researchers sequenced several\nseparate pieces of the same kidney tumors, 63 to 69% of the mutations were missing from\nat least one piece. In one tumor, the gene ",(0,l.jsx)(t.em,{children:"SETD2"})," had been switched off by a different\nmutation in different regions, so separate branches had found the same way to grow\n(",(0,l.jsx)(t.a,{href:"https://doi.org/10.1056/NEJMoa1113205",children:"Gerlinger et al., 2012"}),"). In 100 early lung\ncancers, mutations in well-known drivers such as ",(0,l.jsx)(t.em,{children:"EGFR"}),", ",(0,l.jsx)(t.em,{children:"BRAF"})," and ",(0,l.jsx)(t.em,{children:"TP53"})," were almost\nalways in the trunk, but more than 75% of the tumors also had drivers that arose later,\nin only some of their cells (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1056/NEJMoa1616288",children:"Jamal-Hanjani et al.,\n2017"}),"). One sample from one part of a tumor can\nmiss these branches."]}),"\n",(0,l.jsx)(t.h2,{id:"reading-clones-in-the-data",children:"Reading Clones in the Data"}),"\n",(0,l.jsxs)(t.p,{children:["A tumor's tree can be estimated from the reads of a single sample. Take a mutation on\none of the two copies of a chromosome. If every cancer cell carries it and the sample\ncontained nothing but tumor, about half the reads covering that position would show the\nmutation. Normal cells in the sample carry only the reference base, so they dilute it.\nIn a sample that is 60% tumor, a clonal mutation shows up in about 30% of the reads, and\na mutation carried by only a third of the cancer cells shows up in about 10%. The share\nof reads showing a variant is its ",(0,l.jsx)(t.a,{href:"/docs/genomic-variation/copy-number-variation#allele-fractions",children:"allele\nfraction"}),", and the\nshare of tumor in the sample is its\n",(0,l.jsx)(t.a,{href:"/docs/genomic-variation/copy-number-variation#tumors-complicate-things",children:"purity"}),"."]}),"\n",(0,l.jsxs)(t.p,{children:["Where a tumor has two copies of a chromosome, clonal mutations therefore pile up around\none allele fraction, and each large subclone adds a smaller pile below it (Figure 2.8).\nCopy number changes can shift these piles. After correcting for purity and copy number,\ntools estimate the share of cancer cells that carry each mutation, its ",(0,l.jsx)(t.strong,{children:"cancer cell\nfraction"}),". They then group mutations with similar fractions, and each group stands for\na likely clone or subclone that can be placed on a tree. Two subclones of similar size\ncan blur into one group, so the tree is an estimate. Sequencing more than one sample\nfrom the same tumor, or the same tumor at more than one time, makes the tree much easier\nto work out."]}),"\n",(0,l.jsxs)(t.figure,{className:"lg-figure lg-figure--tall lg-figure--themed",id:"figure-2-8",children:[(0,l.jsx)(t.img,{alt:"Two panels. At top left, a family tree drawn as lines running left to right. A trunk starts at the first cancer cell and carries three mutations, marked as small circles. Two branches split off from the trunk, subclone A and subclone B, each with two more mutations. All cancer cells carry the trunk mutations. 30% of them have only the trunk mutations, 50% also carry subclone A's mutations and 20% also carry subclone B's. At top right, a circle labeled the sample, 60% cancer cells, is filled with dots for cells from the trunk, from subclone A and from subclone B, mixed with empty dots for normal cells. At bottom, a histogram of how many mutations show each share of reads, from 0 to 50%. Trunk mutations form a peak around 30%, at a dashed line labeled half of 60%. Subclone A mutations form a peak around 15%, and subclone B mutations form a lower peak around 6%.",src:o().A+"",width:"392",height:"484"}),(0,l.jsx)(t.img,{className:"lg-figure__dark",src:a().A,alt:"Two panels. At top left, a family tree drawn as lines running left to right. A trunk starts at the first cancer cell and carries three mutations, marked as small circles. Two branches split off from the trunk, subclone A and subclone B, each with two more mutations. All cancer cells carry the trunk mutations. 30% of them have only the trunk mutations, 50% also carry subclone A's mutations and 20% also carry subclone B's. At top right, a circle labeled the sample, 60% cancer cells, is filled with dots for cells from the trunk, from subclone A and from subclone B, mixed with empty dots for normal cells. At bottom, a histogram of how many mutations show each share of reads, from 0 to 50%. Trunk mutations form a peak around 30%, at a dashed line labeled half of 60%. Subclone A mutations form a peak around 15%, and subclone B mutations form a lower peak around 6%.",width:"392",height:"484",loading:"lazy",decoding:"async"}),(0,l.jsxs)(t.figcaption,{children:[(0,l.jsx)(t.span,{className:"lg-figure__number",children:"Figure 2.8"})," A tumor's family tree and what it looks like in the reads. Every cancer cell carries the trunk mutations, so in a sample that is 60% tumor they appear in about 30% of the reads. Mutations carried by a subclone appear in a smaller share of reads, in proportion to the share of cancer cells that carry them. Based on Dentro et al. (2017). The data are made up."]})]}),"\n",(0,l.jsx)(t.h2,{id:"faster-change",children:"Faster Change"}),"\n",(0,l.jsxs)(t.p,{children:["Some tumors don't wait for mutations to build up one at a time. Losing a ",(0,l.jsx)(t.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#genes-that-guard-the-genome",children:"genome\nguard"})," speeds up\nsmall changes, and other events change large parts of the genome at once."]}),"\n",(0,l.jsxs)(t.ul,{children:["\n",(0,l.jsxs)(t.li,{children:[(0,l.jsx)(t.strong,{children:"Whole-genome doubling."})," A cell copies its genome but doesn't divide, so it ends up\nwith about four copies of every chromosome. Nearly 30% of 9,692 advanced cancers had\nbeen through this. It usually happened early, after a first driver mutation, and\npatients whose tumors had doubled tended to do worse (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1038/s41588-018-0165-1",children:"Bielski et al.,\n2018"}),")."]}),"\n",(0,l.jsxs)(t.li,{children:[(0,l.jsx)(t.strong,{children:"Chromosomal instability."})," Cells that keep gaining and losing pieces of chromosomes\nas they divide produce a steady supply of new variety. In the 100 lung cancers above,\nongoing chromosomal instability went along with greater differences between parts of\nthe same tumor, and more variation in copy number between regions meant a higher risk\nof the cancer coming back or the patient dying."]}),"\n",(0,l.jsxs)(t.li,{children:[(0,l.jsxs)(t.strong,{children:[(0,l.jsx)(t.a,{href:"/docs/genomic-variation/structural-variation#kinds-of-structural-variants",children:"Chromothripsis"}),"."]}),"\nOne or a few chromosomes shatter and are stitched back together in a single event. In\nwhole genomes from 2,658 tumors, it was found in more than half of the tumors of\nseveral kinds of cancer, and it can amplify an oncogene or switch off other genes\n(",(0,l.jsx)(t.a,{href:"https://doi.org/10.1038/s41588-019-0576-7",children:"Cort\xe9s-Ciriano et al., 2020"}),")."]}),"\n"]}),"\n",(0,l.jsx)(t.h2,{id:"spreading",children:"Spreading"}),"\n",(0,l.jsxs)(t.p,{children:["Metastasis is another step in the same process. The cells that seed a metastasis come\nfrom one or more branches of the tumor's tree, so a metastasis shares the trunk and adds\nnew branches of its own. Those branches can split off early or late in the life of the\noriginal tumor (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1126/science.aaf2784",children:"Turajlic and Swanton, 2016"}),").\nIn 126 lung cancers that went on to spread, the subclones that seeded metastases had\nalready expanded inside the original tumor, which suggests they had been selected there.\nIn 25% of cases, the cells that spread had split off early, before the last subclone had\ntaken over the original tumor. In 32%, the metastases were seeded by more than one\nsubclone (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1038/s41586-023-05729-x",children:"Al Bakir et al., 2023"}),")."]}),"\n",(0,l.jsx)(t.h2,{id:"surviving-treatment",children:"Surviving Treatment"}),"\n",(0,l.jsx)(t.p,{children:"Treatment is a strong form of selection. A drug that kills most of a tumor's cells\nleaves behind any cells that can resist it, and those cells are often present before\ntreatment starts. Their descendants become the relapse (Figure 2.9)."}),"\n",(0,l.jsxs)(t.p,{children:["Childhood leukemia showed this clearly. In 61 children with acute lymphoblastic leukemia\nwhose cancer came back after treatment, the leukemia at relapse usually carried a\ndifferent set of copy number changes from the leukemia at diagnosis. Most relapses\nlacked some of the changes seen at diagnosis, so they came from an earlier branch of the\ntree. The cells responsible for the relapse were often already present as a small\nsubclone at diagnosis (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1126/science.1164266",children:"Mullighan et al.,\n2008"}),")."]}),"\n",(0,l.jsxs)(t.p,{children:["In colorectal cancer, studies of drugs that block the receptor EGFR found that tumors\nwithout ",(0,l.jsx)(t.em,{children:"KRAS"})," mutations often responded at first but almost always became resistant\nwithin several months. KRAS passes on the receptor's signal, so a ",(0,l.jsx)(t.em,{children:"KRAS"})," mutation ",(0,l.jsx)(t.a,{href:"/docs/cancer-biology/signaling-pathways#locking-the-relay-on",children:"keeps\nthe relay switched on"})," even when the\nreceptor is blocked. In 24 patients whose tumors had no detectable ",(0,l.jsx)(t.em,{children:"KRAS"})," mutations\nbefore treatment, 9 (38%) later had ",(0,l.jsx)(t.em,{children:"KRAS"})," mutations detected in their blood, usually 5\nto 6 months after starting the drug. Modeling suggested that the resistant cells had\nbeen there all along (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1038/nature11219",children:"Diaz et al., 2012"}),"). Across\n7,108 whole genomes from untreated early tumors and treated metastatic tumors, treatment\nhad selected for known resistance mutations in 32% of treated patients and for likely\nones in another 21% (",(0,l.jsx)(t.a,{href:"https://doi.org/10.1038/s41586-023-06054-z",children:"Mart\xednez-Jim\xe9nez et al.,\n2023"}),")."]}),"\n",(0,l.jsxs)(t.figure,{className:"lg-figure lg-figure--themed",id:"figure-2-9",children:[(0,l.jsx)(t.img,{alt:"A plot with time running left to right and the height of each shape showing how many cancer cells there are. Labels along the top mark diagnosis, remission and relapse. The main clone grows from a point and is largest at diagnosis. A second subclone arises inside it and takes up much of its upper half by diagnosis. Two dashed lines close to the middle mark the limit of detection. A thin resistant subclone runs inside the main clone, below the limit of detection, labeled already there but too small to notice. During a shaded band labeled treatment, the main clone and the second subclone shrink away to nothing. At remission, the remaining cells fall below the limit of detection, with a line pointing to them labeled too few cells to detect. The resistant cells then keep growing and fill the whole plot by relapse.",src:r().A+"",width:"392",height:"340"}),(0,l.jsx)(t.img,{className:"lg-figure__dark",src:s().A,alt:"A plot with time running left to right and the height of each shape showing how many cancer cells there are. Labels along the top mark diagnosis, remission and relapse. The main clone grows from a point and is largest at diagnosis. A second subclone arises inside it and takes up much of its upper half by diagnosis. Two dashed lines close to the middle mark the limit of detection. A thin resistant subclone runs inside the main clone, below the limit of detection, labeled already there but too small to notice. During a shaded band labeled treatment, the main clone and the second subclone shrink away to nothing. At remission, the remaining cells fall below the limit of detection, with a line pointing to them labeled too few cells to detect. The resistant cells then keep growing and fill the whole plot by relapse.",width:"392",height:"340",loading:"lazy",decoding:"async"}),(0,l.jsxs)(t.figcaption,{children:[(0,l.jsx)(t.span,{className:"lg-figure__number",children:"Figure 2.9"})," Treatment selects a resistant subclone. Treatment kills the main clone and one of its subclones, but not a small resistant subclone that was already present at diagnosis. The resistant subclone stays below the limit of detection until, after a remission, it grows into the relapse. Based on Mullighan et al. (2008) and Diaz et al. (2012). The data are made up."]})]}),"\n",(0,l.jsx)(t.h2,{id:"up-next",children:"Up Next"}),"\n",(0,l.jsxs)(t.p,{children:["Every change on this page arose during a person's lifetime. Some people are born with a\nfirst hit already in every cell. ",(0,l.jsx)(t.a,{href:"/docs/cancer-biology/inherited-risk",children:"Inherited Risk"})," covers the genes\ninvolved and how often they explain cancer in children."]})]})}function g(e={}){const{wrapper:t}={...(0,c.R)(),...e.components};return t?(0,l.jsx)(t,{...e,children:(0,l.jsx)(f,{...e})}):f(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>i});var a=n(6540);const s={},o=a.createContext(s);function r(e){const t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);